import{ax as i,A as t,aQ as e,z as a}from"./chunks/framework.BWRXlwpK.js";const v=JSON.parse('{"title":"介绍","description":"","frontmatter":{},"headers":[],"relativePath":"webpack/vite/intro.md","filePath":"webpack/vite/intro.md","lastUpdated":1788400509000}'),s={name:"webpack/vite/intro.md"};function o(r,l,c,p,n,u){return a(),t("div",null,l[0]||(l[0]=[e('<h1 id="介绍" tabindex="-1">介绍 <a class="header-anchor" href="#介绍" aria-label="Permalink to &quot;介绍&quot;">​</a></h1><p>Vite是用于替代webpack的打包工具，他比webpack更快。</p><p><strong>Vite主要由两部分构成：</strong></p><ul><li>一个开发服务器，它基于原生ES模块提供了丰富的内建功能，如：速度快到惊人的模块热更新。</li><li>一套构建指令，它使用Rollup打包你的代码，并且它是预配置的，可输出用于生产环境的高度优化过的静态资源。</li></ul><p><strong>分为以下模块：</strong></p><ul><li><ol><li>什么是构建工具</li></ol></li><li><ol start="2"><li>相比于webpack的优势</li></ol></li><li><ol start="3"><li>es module的规范</li></ol></li><li><ol start="4"><li>vite到底是什么</li></ol></li><li><ol start="5"><li>vite的安装与使用</li></ol></li><li><ol start="6"><li>vite的编译结果</li></ol></li><li><ol start="7"><li>vite的编译结果分析</li></ol></li><li><ol start="8"><li>vite的配置文件</li></ol></li><li><ol start="9"><li>vite处理css，静态资源怎么去做</li></ol></li><li><ol start="10"><li>vite的插件以及常用插件的使用</li></ol></li><li><ol start="11"><li>vite与ts的结合</li></ol></li><li><ol start="12"><li>vite构建react项目、svelte项目、vue3项目</li></ol></li><li><ol start="13"><li>vite构建原理</li></ol></li></ul><h2 id="什么是构建工具" tabindex="-1">什么是构建工具 <a class="header-anchor" href="#什么是构建工具" aria-label="Permalink to &quot;什么是构建工具&quot;">​</a></h2><p>浏览器只认识html、css、js</p><p>在企业级开发中可能还会使用其他技术，这时需要构建工具将这些内容转换成浏览器可以使用的内容，同时可以对要展示的资源进行优化。</p><p>如：</p><ul><li>typescript：需要将tsc将ts文件内容转换为js</li><li>React / Vue：需要react-compiler / vue-complier 处理React / Vue 中的模板(.jsx/.vue)</li><li>预处理css：less/scss/postcss/component-style等预处理css需要使用其对应的less-loader，sass-loader等一系列编译工具</li><li>语法降级：babel ---》 将es的新语法降级为旧版浏览器可以接受的语法</li><li>体积优化：uglifyjs ---》将我们的代码进行压缩变得体积更小</li><li>模块合并：将多个文件整合到一个文件中，减少资源请求</li><li>代码分割：提取多个页面的公共代码，提起首屏不需要执行部分代码让其异步加载。</li><li>...</li></ul>',11)]))}const m=i(s,[["render",o]]);export{v as __pageData,m as default};
